type StepStatusProps = {
  steps: string[];
  activeIndex: number;
};

export function StepStatus({ steps, activeIndex }: StepStatusProps) {
  return (
    <div className="space-y-3">
      {steps.map((step, index) => {
        const isActive = index === activeIndex;
        const isDone = index < activeIndex;
        return (
          <div
            key={step}
            className={`flex items-center justify-between px-4 py-3 brutal-card ${
              isActive ? "bg-signal text-ink" : "bg-bone"
            }`}
          >
            <div className="font-mono text-sm uppercase tracking-wide">{step}</div>
            <div className="text-xs">
              {isDone ? "done" : isActive ? "working" : "queued"}
            </div>
          </div>
        );
      })}
    </div>
  );
}
